module pll (
    input wire clk_in,
    input wire reset,
    input wire [7:0] control_voltage,
    output reg clk_out
);
    reg [3:0] phase_counter;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            phase_counter <= 0;
            clk_out <= 0;
        end else begin
            phase_counter <= phase_counter + 1;
            if (phase_counter == control_voltage[3:0]) begin
                clk_out <= ~clk_out;
            end
        end
    end
endmodule

