module LU_Decomposition (
    input [31:0] a11,
    input [31:0] a12,
    input [31:0] a21,
    input [31:0] a22,
    output reg [31:0] l11,
    output reg [31:0] l21,
    output reg [31:0] u11,
    output reg [31:0] u12,
    output reg [31:0] u22
);
    always @* begin
        l11 = a11;
        u11 = a11;
        l21 = a21 / u11; // Assuming u11 is not zero
        u12 = a12;
        u22 = a22 - l21 * u12;
    end
endmodule

