module echo_cancellation(  
    input clk,  
    input reset,  
    input [15:0] input_signal,  
    input [15:0] reference_signal,  
    output reg [15:0] output_signal,  
    output reg [15:0] filter_coeff  
);  

    reg [15:0] error;  
    reg [15:0] mu = 16'h0001; // Step size for LMS  
    reg [15:0] predicted_signal;  
    reg [15:0] coefficient_adjustment;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            output_signal <= 16'b0;  
            filter_coeff <= 16'b0;  
        end else begin  
            predicted_signal <= filter_coeff * reference_signal;  
            error <= input_signal - predicted_signal;  
            coefficient_adjustment <= (mu * error * reference_signal) >> 16;  
            filter_coeff <= filter_coeff + coefficient_adjustment;  
            output_signal <= predicted_signal;  
        end  
    end  
endmodule

