module clock_divider (
    input clk_in,
    input rst,
    output reg clk_out
);

reg [1:0] count;

always @(posedge clk_in or posedge rst) begin
    if (rst) begin
        count <= 0;
        clk_out <= 0;
    end else begin
        count <= count + 1;
        if (count == 3) begin
            clk_out <= ~clk_out;
            count <= 0;
        end
    end
end

endmodule

