module i2c_controller (
    input clk,
    input rst,
    input start,
    input [7:0] data_in,
    input read,
    output reg sda,
    output reg scl,
    output reg [7:0] data_out,
    output reg busy
);

    reg [3:0] state;
    reg [3:0] bit_count;
    reg [7:0] shift_reg;

    localparam IDLE = 4'd0,
               START = 4'd1,
               SEND = 4'd2,
               RECV = 4'd3,
               STOP = 4'd4;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            busy <= 0;
            sda <= 1;
            scl <= 0;
            bit_count <= 0;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        busy <= 1;
                        state <= START;
                    end
                end
                START: begin
                    sda <= 0; // Start condition
                    scl <= 0;
                    state <= SEND;
                    shift_reg <= data_in;
                    bit_count <= 0;
                end
                SEND: begin
                    if (bit_count < 8) begin
                        sda <= shift_reg[7]; // Send most significant bit first
                        shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left
                        scl <= 1; // Clock high
                        scl <= 0; // Clock low
                        bit_count <= bit_count + 1;
                    end else begin
                        if (read) begin
                            state <= RECV;
                        end else begin
                            state <= STOP;
                        end
                    end
                end
                RECV: begin
                    if (bit_count < 8) begin
                        scl <= 1; // Clock high
                        data_out <= {data_out[6:0], sda}; // Shift in data
                        scl <= 0; // Clock low
                        bit_count <= bit_count + 1;
                    end else begin
                        state <= STOP;
                    end
                end
                STOP: begin
                    sda <= 0; // Stop condition
                    scl <= 1;
                    sda <= 1;
                    busy <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

