module tcp_segmenter(  
    input wire clk,  
    input wire [31:0] data_in,  
    output reg [7:0] segment_out,  
    output reg valid  
);  
    reg [2:0] state;  
    parameter IDLE = 3'b000, SEG1 = 3'b001, SEG2 = 3'b010, SEG3 = 3'b011, SEG4 = 3'b100;  

    always @(posedge clk) begin  
        case (state)  
            IDLE: begin  
                valid <= 0;  
                state <= SEG1;  
            end  
            SEG1: begin  
                segment_out <= data_in[31:24];  
                valid <= 1;  
                state <= SEG2;  
            end  
            SEG2: begin  
                segment_out <= data_in[23:16];  
                valid <= 1;  
                state <= SEG3;  
            end  
            SEG3: begin  
                segment_out <= data_in[15:8];  
                valid <= 1;  
                state <= SEG4;  
            end  
            SEG4: begin  
                segment_out <= data_in[7:0];  
                valid <= 1;  
                state <= IDLE;  
            end  
            default: begin  
                state <= IDLE;  
            end  
        endcase  
    end  
endmodule

