module SR_latch (
    input wire S,
    input wire R,
    output reg Q,
    output reg Qn
);
    always @(S or R) begin
        if (S && !R) begin
            Q <= 1;
            Qn <= 0;
        end else if (!S && R) begin
            Q <= 0;
            Qn <= 1;
        end else if (S && R) begin
            // Invalid state, hold previous state
            Q <= Q; // latch retains its state
            Qn <= Qn; // latch retains its state
        end
    end
endmodule

