module PLL (
    input wire clk_ref,         // Reference clock input
    input wire reset,           // Asynchronous reset
    input wire [3:0] div_factor, // Division factor (1 to 15)
    output reg clk_out          // Output clock signal
);
    reg [3:0] counter;          // Counter for division
    reg clk_div;                // Divided clock signal

    // Generate divided clock signal
    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            counter <= 0;
            clk_div <= 0;
        end else begin
            if (counter == div_factor - 1) begin
                clk_div <= ~clk_div;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    // Assign the divided clock signal to output
    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            clk_out <= 0;
        end else begin
            clk_out <= clk_div;
        end
    end
endmodule

