module crystal_oscillator (
    input wire clk,
    input wire reset,
    output reg out
);
    reg [2:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 3'b000;
            out <= 0;
        end else begin
            if (counter == 3'b101) begin // Toggle output at 5
                out <= ~out;
                counter <= 3'b000; // Reset counter
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

