module simple_neural_net (
    input wire clk,
    input wire reset,
    input wire [7:0] input_features, // 8-bit input features
    input wire [7:0] target_output,   // 8-bit target output
    output reg [7:0] actual_output     // 8-bit actual output
);

    reg [7:0] weights;                // 8-bit weight
    reg [7:0] error;                  // Error calculation
    reg [7:0] learning_rate = 8'd1;   // Fixed learning rate

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            weights <= 8'd0;          // Initialize weights to zero
            actual_output <= 8'd0;    // Initialize actual output to zero
        end else begin
            // Forward pass (simple weighted sum)
            actual_output <= input_features * weights;

            // Error calculation
            error <= target_output - actual_output;

            // Weight update (backpropagation step)
            weights <= weights + (error * learning_rate);
        end
    end
endmodule

