module chebyshev_filter (
    input clk,
    input rst,
    input signed [15:0] x,
    output reg signed [15:0] y
);
    reg signed [15:0] x1, x2; // Delayed inputs
    reg signed [15:0] y1, y2; // Delayed outputs

    parameter signed [15:0] a0 = 16'h0001; // Coefficient scale
    parameter signed [15:0] a1 = 16'h0002;
    parameter signed [15:0] a2 = 16'h0001;
    parameter signed [15:0] b1 = 16'hFFCD; // -0.3 in 2's complement
    parameter signed [15:0] b2 = 16'h0002; // 0.2 in 2's complement

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 0;
            x1 <= 0;
            x2 <= 0;
            y1 <= 0;
            y2 <= 0;
        end else begin
