module pll (
    input wire clk_in,         // Input clock
    input wire reset,         // Reset signal
    output reg clk_out        // Output clock
);
    reg [1:0] divider;         // 2-bit divider for output clock
    reg [1:0] state;           // State for PLL

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            divider <= 0;
            clk_out <= 0;
            state <= 0;
        end else begin
            divider <= divider + 1;
            if (divider == 2) begin // Change clk_out every 2 input clocks
                clk_out <= ~clk_out;
                divider <= 0;
            end
        end
    end
endmodule

