module spi_controller (  
    input wire clk,  
    input wire reset,  
    input wire cs,  
    input wire mosi,  
    output reg miso,  
    output reg sck,  
    input wire mode, // mode = 0 or 1 for SPI Mode 0 or 3  
    output reg [7:0] data_out  
);  

    reg [2:0] bit_count;  
    reg [7:0] data_in;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bit_count <= 0;  
            data_in <= 0;  
            data_out <= 0;  
            miso <= 0;  
            sck <= 0;  
        end else if (cs == 0) begin  
            if (bit_count < 8) begin  
                sck <= (mode == 0) ? ~sck : sck; // Toggle SCK for mode 0  
                data_in[7 - bit_count] <= mosi;  
                bit_count <= bit_count + 1;  
            end else begin  
                data_out <= data_in;  
                miso <= data_in[7];  
                bit_count <= 0;  
            end  
        end else begin  
            sck <= 0;  
            bit_count <= 0;  
        end  
    end  
endmodule

