module pwm_generator(  
    input wire clk,  
    input wire rst,  
    input wire [9:0] duty_cycle,  
    output reg pwm_out  
);  
    reg [9:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 10'b0;  
            pwm_out <= 1'b0;  
        end else begin  
            if (counter < duty_cycle)  
                pwm_out <= 1'b1;  
            else  
                pwm_out <= 1'b0;  

            counter <= counter + 1'b1;  
            if (counter >= 10'd1023)  
                counter <= 10'b0;  
        end  
    end  
endmodule

