module spi_master (
    input clk,
    input rst,
    input mosi,
    input start,
    input [7:0] data_in,
    output reg sclk,
    output reg cs,
    output reg [7:0] data_out,
    output reg done
);

    reg [2:0] bit_count;
    reg [7:0] shift_reg;
    reg state;

    parameter IDLE = 1'b0, TRANSFER = 1'b1;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sclk <= 0;
            cs <= 1;
            data_out <= 8'b0;
            done <= 0;
            bit_count <= 3'b0;
            shift_reg <= 8'b0;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    cs <= 1; // Chip select inactive
                    if (start) begin
                        shift_reg <= data_in; // Load data
                        bit_count <= 3'b0;
                        state <= TRANSFER;
                        done <= 0;
                    end
                end

                TRANSFER: begin
                    cs <= 0; // Chip select active
                    sclk <= ~sclk; // Toggle clock
                    if (sclk) begin
                        data_out[7 - bit_count] <= mosi; // Receive data
                        shift_reg <= {shift_reg[6:0], 1'b0}; // Shift data out
                        bit_count <= bit_count + 1;
                        if (bit_count == 3'd7) begin
                            done <= 1; // Transfer complete
                            state <= IDLE;
                        end
                    end
                end
            endcase
        end
    end
endmodule

module interrupt_controller (
    input wire clk,
    input wire reset,
    input wire [3:0] interrupts,
    output reg interrupt_ack
);
    reg [1:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            interrupt_ack <= 0;
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin
                    if (interrupts != 4'b0000) begin
                        interrupt_ack <= 1;
                        state <= 2'b01;
                    end
                end
                2'b01: begin
                    interrupt_ack <= 0;
                    state <= 2'b00;
                end
            endcase
        end
    end
endmodule

