module sr_flip_flop (
    input wire clk,
    input wire S,
    input wire R,
    output reg Q,
    output reg Qn
);
    always @(posedge clk) begin
        if (S && ~R) begin
            Q <= 1;
            Qn <= 0;
        end else if (~S && R) begin
            Q <= 0;
            Qn <= 1;
        end else if (S && R) begin
            // Invalid state, Q and Qn can be unpredictable
            // but let's hold the last state
            Q <= Q; 
            Qn <= Qn; 
        end
        // If both S and R are low, previous state is retained
    end
endmodule

module median_filter (
    input [7:0] a,
    input [7:0] b,
    input [7:0] c,
    output reg [7:0] median
);

always @(*) begin
    if ((a >= b && a <= c) || (a <= b && a >= c))
        median = a;
    else if ((b >= a && b <= c) || (b <= a && b >= c))
        median = b;
    else
        median = c;
end

endmodule

