module divide_by_8 (  
    input clk,  
    input rst,  
    output reg out  
);  
    reg [2:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 3'b000;  
            out <= 1'b0;  
        end else begin  
            if (counter == 3'b111) begin  
                counter <= 3'b000;  
                out <= 1'b1;  
            end else begin  
                counter <= counter + 1;  
                out <= 1'b0;  
            end  
        end  
    end  
endmodule

