module ethernet_mac_controller(  
    input clk,  
    input reset,  
    input [7:0] data_in,  
    input valid,  
    output reg [7:0] data_out,  
    output reg ready  
);  
    reg [2:0] state;  
    reg [7:0] buffer;  
    parameter IDLE = 3'b000, RECEIVE = 3'b001, DELAY = 3'b010, OUTPUT = 3'b011;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            data_out <= 8'b0;  
            ready <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (valid) begin  
                        buffer <= data_in;  
                        state <= RECEIVE;  
                    end  
                end  
                RECEIVE: begin  
                    if (valid) begin  
                        state <= DELAY;  
                    end  
                end  
                DELAY: begin  
                    state <= OUTPUT;  
                end  
                OUTPUT: begin  
                    data_out <= buffer;  
                    ready <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

