module quarter_round(
    input  [31:0] a, b, c, d,
    output [31:0] a_out, b_out, c_out, d_out
);
    wire [31:0] b_temp, d_temp, c_temp, a_temp;

    // Perform the quarter round operations
    assign b_temp = b ^ ((a + d) << 16);
    assign c_temp = c ^ ((b_temp + a) << 12);
    assign d_temp = d ^ ((c_temp + b_temp) << 8);
    assign a_temp = a ^ ((d_temp + c_temp) << 7);

    // Assign the outputs
    assign a_out = a_temp;
    assign b_out = b_temp;
    assign c_out = c_temp;
    assign d_out = d_temp;
endmodule

module DES_round (
    input wire [7:0] data_in,
    input wire [7:0] key,
    output wire [7:0] data_out
);
    // Initial Permutation (IP)
    wire [7:0] ip;
    assign ip = {data_in[1], data_in[5], data_in[2], data_in[0], data_in[3], data_in[7], data_in[4], data_in[6]}; // a simple IP

    // Round Function
    wire [7:0] round_output;
    assign round_output = ip ^ key; // simple XOR round function

    // Final Permutation (FP)
    assign data_out = {round_output[3], round_output[0], round_output[2], round_output[6], 
                       round_output[4], round_output[7], round_output[5], round_output[1]}; // a simple FP
endmodule

