module serializer_16bit(  
    input clk,  
    input rst,  
    input [15:0] data_in,  
    output reg serial_out  
);  
    reg [3:0] count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 0;  
            serial_out <= 0;  
        end else if (count < 16) begin  
            serial_out <= data_in[15 - count];  
            count <= count + 1;  
        end  
    end  
endmodule

module quarter_round (
    input clk,
    input reset,
    input [31:0] a, b, c, d,
    output reg [31:0] out_a, out_b, out_c, out_d
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out_a <= 32'b0;
            out_b <= 32'b0;
            out_c <= 32'b0;
            out_d <= 32'b0;
        end else begin
            out_a <= a + b;
            out_d <= (d ^ out_a) << 16;
            out_c <= c + out_d;
            out_b <= (b ^ out_c) << 12;
            out_a <= out_a + out_b;
            out_d <= (out_d ^ out_a) << 8;
            out_c <= out_c + out_d;
            out_b <= (out_b ^ out_c) << 7;
        end
    end
endmodule

